// Quarter-wave cosine ROM: cos(2*pi*idx/128), idx = 0..32, Q1.15 (1.0 is 32767).
// Every twiddle factor and the Hann window of the AE-FFT accelerator come from these 33 values.
// Generated by sim/fft/model/aefft_model.py (COS_ROM).

module fft_cos_rom (
  input  logic        [5:0] idx_i,
  output logic signed [15:0] val_o
);

  always_comb begin
    unique case (idx_i)
      6'd0: val_o = 16'sd32767;
      6'd1: val_o = 16'sd32729;
      6'd2: val_o = 16'sd32610;
      6'd3: val_o = 16'sd32413;
      6'd4: val_o = 16'sd32138;
      6'd5: val_o = 16'sd31786;
      6'd6: val_o = 16'sd31357;
      6'd7: val_o = 16'sd30853;
      6'd8: val_o = 16'sd30274;
      6'd9: val_o = 16'sd29622;
      6'd10: val_o = 16'sd28899;
      6'd11: val_o = 16'sd28106;
      6'd12: val_o = 16'sd27246;
      6'd13: val_o = 16'sd26320;
      6'd14: val_o = 16'sd25330;
      6'd15: val_o = 16'sd24279;
      6'd16: val_o = 16'sd23170;
      6'd17: val_o = 16'sd22006;
      6'd18: val_o = 16'sd20788;
      6'd19: val_o = 16'sd19520;
      6'd20: val_o = 16'sd18205;
      6'd21: val_o = 16'sd16846;
      6'd22: val_o = 16'sd15447;
      6'd23: val_o = 16'sd14010;
      6'd24: val_o = 16'sd12540;
      6'd25: val_o = 16'sd11039;
      6'd26: val_o = 16'sd9512;
      6'd27: val_o = 16'sd7962;
      6'd28: val_o = 16'sd6393;
      6'd29: val_o = 16'sd4808;
      6'd30: val_o = 16'sd3212;
      6'd31: val_o = 16'sd1608;
      6'd32: val_o = 16'sd0;
      default: val_o = 16'sd0;
    endcase
  end

endmodule
